const UA = 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1';

let appConfig = { ver: 1, title: '央视新闻联播', site: 'https://content-static.cctvnews.cctv.com', tabs: [{ name: '新闻联播', ext: { id: 'cctv_news' } }] };

async function getConfig() { return JSON.stringify(appConfig); }

async function getCards(ext) {
    const latest = DATA[0];
    return JSON.stringify({
        list: [{
            vod_id: 'cctv_news',
            vod_name: '《新闻联播》合集',
            vod_pic: latest ? latest.cover : '',
            vod_remarks: '共 ' + DATA.length + ' 集 | 最新: ' + (latest ? latest.name : '暂无'),
            vod_duration: '30分钟',
            ext: { id: 'cctv_news' }
        }],
        filter: []
    });
}

async function getTracks(ext) {
    const tracks = DATA.map(function(ep, i){ return { name: ep.name, ext: { index: i, url: ep.url } }; });
    return JSON.stringify({ list: [{ title: '默认线路', tracks }] });
}

async function getPlayinfo(ext) {
    ext = JSON.parse(ext);
    if (!ext.url) return JSON.stringify({ urls: [] });
    return JSON.stringify({
        urls: [ext.url],
        headers: [
            { 'User-Agent': UA },
            { 'Referer': 'https://tv.cctv.com/' }
        ]
    });
}

async function search(ext) { return await getCards(ext); }
